import{_ as t,l as n,o as a,c as i,v as s,p as l,x as e,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"Kosmos-1 / 2","description":"","frontmatter":{"title":"Kosmos-1 / 2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kosmos.md","filePath":"llm/kosmos.md","lastUpdated":1789023840000}'),E={name:"llm/kosmos.md"};function A(g,o,h,c,u,B){const r=n("Mermaid");return a(),i("div",null,[o[1]||(o[1]=s('<h1 id="kosmos-1-2" tabindex="-1">Kosmos-1 / 2 <a class="header-anchor" href="#kosmos-1-2" aria-label="Permalink to &quot;Kosmos-1 / 2&quot;">​</a></h1><div class="epigraph"><p>语言不是你需要的全部：把感知对齐进因果语言模型之后，再用 Markdown 式超链接把短语钉到离散位置码上，接地才能成为与下一词预测同一套解码。</p><footer>—— Huang 等，Kosmos-1，arXiv:2302.14045；Peng 等，Kosmos-2，arXiv:2306.14824</footer></div><p>微软 2023 年的 <strong>Kosmos</strong> 把「通用多模态 LLM」写得很早、容量却刻意不大。<strong>Kosmos-1</strong>（NeurIPS 2023）是约 <strong>1.6B</strong> 的 MAGNETO 因果 Transformer：CLIP 系视觉编码器加 resampler，吃文本、图文对与交错网页，做零样本 / 少样本看图与 OCR 苗头。<strong>Kosmos-2</strong>（ICLR 2024）不改结构，从 Kosmos-1 初始化，把 <strong>GRIT</strong> 接地图文对加进语料，用位置 token 把字幕里的短语链到框。本篇写 1 的感知对齐与 2 的接地格式；不把 Kosmos-G / 后续更名型号的层表写进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2023 年初，GPT-3 已经证明语言侧的上下文学习，视觉仍多是独立的 caption / VQA 专家。要把感知接进<strong>同一个</strong>下一词解码器，需要：视觉特征如何变成语言模型能读的前缀；交错文档如何提供「图在句子中间」的梯度；容量只有约 1.6B 时，不能靠堆 70B 掩盖对齐错误。Kosmos-1 的问题是对齐与通用性，不是竞赛级 MMMU。</p><p>Kosmos-1 仍不能指物。用户画一个框问「这个」，或模型说「左边那只猫」却不输出坐标，交互停在纯文本。检测器外挂会把 LLM 变成配音。Kosmos-2 要的是：框与短语都是词表里的离散符号，接地任务仍是语言建模。</p><h3 id="magneto-小模型-不是冻住的-65b-flamingo" tabindex="-1">MAGNETO 小模型，不是冻住的 65B Flamingo <a class="header-anchor" href="#magneto-小模型-不是冻住的-65b-flamingo" aria-label="Permalink to &quot;MAGNETO 小模型，不是冻住的 65B Flamingo&quot;">​</a></h3><p>语言骨干：24 层 MAGNETO，隐维 2048，32 头，FFN 8192。视觉：24 层、隐维 1024、FFN 4096，输入 \\(224\\times 224\\)、patch 14。图像经编码器与 resampler 变成一段连续嵌入，用特殊符号标出图像段起止，再与文本嵌入拼接。可训练参数合计约 1.6B。MAGNETO 相对标准 Pre-LN 在子层上多归一化，论文把它当作跨模态训练稳定性的选择。损失只计离散 token——文本；连续视觉前缀当条件。</p><p><span class="marginnote">1.6B 是全模型口径。不要写成「1.3B 语言 + 可忽略视觉」。分辨率 224 决定细字上限；Kosmos-2 的 32×32 位置网格是在这张小画布上切 bin，不是高分辨率检测器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Kosmos-1 数据：纯文本、图文对、交错图文。训练目标一律下一词。评测走 caption、VQA、OCR 相关与语言理解，并展示少样本多模态。Kosmos-2 在此之上加入 GRIT：从 LAION-2B 与 COYO-700M 子集抽字幕，抽取名词短语与指称，用检测 / 接地管线把短语链到框，再写成超链接式字符串。连续坐标离散化：宽高各 32 bin（每 bin \\(7\\times 7\\) 像素），词表加 <strong>1024</strong> 个位置 token。框写成起点与终点两个位置码，可多框、用分隔符。Markdown 风格把「短语」链到「位置码序列」。训练仍只对文本与位置码计损失。指令阶段混 LLaVA-Instruct、语言指令，以及由 GRIT 构造的「给短语出框 / 给框出短语」。</p><h3 id="指与被指是同一套位置码" tabindex="-1">指与被指是同一套位置码 <a class="header-anchor" href="#指与被指是同一套位置码" aria-label="Permalink to &quot;指与被指是同一套位置码&quot;">​</a></h3><p>接地：提示里写短语，模型续位置码。指称：用户提供位置码（或代词 + 框），模型在条件于该区域时回答。把 <code>&lt;grounding&gt;</code> 一类控制符加在 caption 前，可得到带框的描述。论文报告短语接地、指称理解 / 生成，以及与 Kosmos-1 对照的 Flickr30k / VQAv2：接地能力加上去之后，VQA 略降、caption 略升——技能组合不是免费扩容。</p>',13)),(a(),l(p,null,{default:e(()=>[d(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22224%C3%97224%20%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20VE%5B%22%E8%A7%86%E8%A7%89%E7%BC%96%E7%A0%81%E5%99%A8%20%2B%20resampler%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%20%2F%20%E4%BA%A4%E9%94%99%E6%96%87%E6%A1%A3%22%5D%20--%3E%20LM%5B%221.6B%20MAGNETO%20%E5%9B%A0%E6%9E%9C%20LM%22%5D%0A%20%20VE%20--%3E%20LM%0A%20%20GRIT%5B%22GRIT%20%E7%9F%AD%E8%AF%AD-%E6%A1%86%E5%AF%B9%22%5D%20--%3E%20LOC%5B%2232%C3%9732%20%E4%BD%8D%E7%BD%AE%20token%22%5D%0A%20%20LOC%20--%3E%20LM%0A%20%20LM%20--%3E%20W%5B%22%E4%B8%8B%E4%B8%80%E8%AF%8D%22%5D%0A%20%20LM%20--%3E%20B%5B%22%E6%A1%86%EF%BC%9A%E4%BD%8D%E7%BD%AE%E7%A0%81%22%5D%0A"})]),fallback:e(()=>[...o[0]||(o[0]=[m(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Kosmos-1 的机制是：视觉前缀占用上下文里的一段键值，后续词的查询可以读图；交错数据让「后文指前文的图」出现在预训练里，而不只出现在微调模板。容量小，世界知识浅，零样本更像格式与感知对齐，而不是学科推理。</p><p>Kosmos-2 把几何收进词表：位置码与词在同一 softmax 里竞争。模型学的是「短语之后该接哪两个 bin」，而不是回归头上的 \\(L_1\\) 框损失。超链接格式提供对齐监督：短语跨度与框在同一序列邻接，注意力不必跨整段字幕去猜指称。32×32 量化把框误差钉在约 7 像素，对 224 图够用，对 4K 截图不够——那不是加几个 token 能解决的，要把编码器分辨率一起抬。</p><h3 id="和检测头、和更晚的接地-mllm" tabindex="-1">和检测头、和更晚的接地 MLLM <a class="header-anchor" href="#和检测头、和更晚的接地-mllm" aria-label="Permalink to &quot;和检测头、和更晚的接地 MLLM&quot;">​</a></h3><p>外挂检测器：LLM 输出文本再由 Grounding-DINO 找框，两套误差。Kosmos-2 是单解码器。更晚的 Shikra、Kosmos 谱系之外的 grounded LLaVA，容量与分辨率都大一号，榜不可直接当「格式赢了」。Kosmos-2 的贡献是<strong>数据格式 + 小模型可训</strong>，不是 2024 年开源 70B 的 OCR 上限。</p><p><span class="marginnote">语言任务表上 Kosmos-2 与 1 大致持平、个别 SuperGLUE 有升有降。不要写成「接地必然伤害语言」或「必然提升」；原文的叙事是「新能力、旧任务可比」。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>1.6B 进不了和 GPT-4V 同一张雷达图。224 输入、resampler 压缩，文档理解不是产品目标。GRIT 来自网页图文，框噪声、短语对齐错误会变成位置码上的标签噪声。位置词表与聊天模板绑死，换视觉塔分辨率必须重定义 bin，不能热插拔 448 编码器还用 32×32、7 像素 bin。推理要约束位置码的语法（起止、范围、成对），否则会抽到非法索引。</p><p>不要把 MAGNETO 写成普通 Llama 层表。不要把 Kosmos-1 的少样本当 Flamingo-80B 的少样本。开源实现（Transformers 的 Kosmos-2）用 <code>&lt;patch_index_xxxx&gt;</code> 一类表面形式，应与论文 Markdown 超链接对照，而不是混用两种模板还怪模型不会接地。</p><p>服务上「用户画框」要把像素坐标映射到 32×32 再写成位置码，映射错一档表现为指错物体。生成框后要把 bin 映回像素再画，评估用官方量化，不要在连续坐标上另算 IoU 还声称复现失败。网页接地数据含人物与商标，产品层仍要过滤。</p><p><span class="marginnote">出处：Huang 等，<em>Language Is Not All You Need: Aligning Perception with Language Models</em>，arXiv:2302.14045（NeurIPS 2023）；Peng 等，<em>Grounding Multimodal Large Language Models to the World</em>，arXiv:2306.14824（ICLR 2024）。架构细节以 Kosmos-2 文中复述的 24/2048/32 为准。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kosmos-1 用约 1.6B MAGNETO + 视觉 resampler 做感知与语言的因果对齐，数据含交错图文。</li><li>Kosmos-2 同一结构，加 GRIT 与 32×32 位置 token，把接地写成下一词问题。</li><li>指与被指共用位置码；VQA 相对一代略有波动，不是免费技能包。</li><li>分辨率与容量决定它是格式论文，不是高分辨率文档模型。</li><li>出处：Huang 等 arXiv:2302.14045；Peng 等 arXiv:2306.14824。</li></ul>',13))])}const _=t(E,[["render",A]]);export{L as __pageData,_ as default};
